package io.github.terryyyc.fakexxx.contract.v1

import android.os.Parcel
import android.os.Parcelable
import org.junit.Assert.assertEquals
import org.junit.Assert.fail
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner

/**
 * Golden BYTE-LAYOUT pins for every Parcelable of the environment-control
 * contract v1 — the #186 root fix.
 *
 * **Incident (#186, evidence in #191).** Two APKs built from this ONE shared
 * source module in DIFFERENT build batches disagreed at the parcel-codegen
 * level: the writer emitted nullable payload fields as bare `writeParcelable`,
 * while the reader expected a null-flag int + CREATOR. Binder then decoded
 * misaligned bytes and `PreflightReportV1.acceptedIntentHash` arrived null ->
 * NPE -> discover 恒失败. Source was identical on both sides; the ARTIFACTS
 * were not. Field-equality round trips (see [ContractRoundTripTest]) cannot
 * catch this: each build round-trips against itself and is green. Only a
 * byte-level anchor shared by both builds can.
 *
 * **Why this test catches it.** The contract module is compiled SEPARATELY by
 * each consuming Gradle root (apps/cellrebel-auto, apps/qianwangyou — see
 * settings.gradle include + projectDir override, and
 * scripts/check-contract-v1.sh section 4, which runs this very module's
 * `testDebugUnitTest` from both roots). Each execution therefore exercises
 * THAT root's kotlin-parcelize output: writer via writeToParcel (exactly what
 * AIDL typed parameters put on the Binder wire), reader via the generated
 * CREATOR. Both roots must reproduce the SAME committed golden bytes.
 *
 * **What is pinned.**
 *  - [PreflightReportV1]: ALL 2^4 = 16 null/non-null combinations of its
 *    nullable fields (the #186 incident type) — bit order b0=waitUntilEpochMs,
 *    b1=scheduleItemId, b2=scheduleVersion, b3=exhausted.
 *  - [EnvironmentObservationV1]: ALL 2^6 = 64 combinations — b0=
 *    continuitySinceEpochMs, b1=continuitySinceElapsedRealtimeMs,
 *    b2=deliveryModeWire, b3=effectiveLatitude, b4=effectiveLongitude,
 *    b5=isMock.
 *  - [CapabilitySnapshotV1]: all 64 LEGAL states (2 schedule-group states per
 *    the §6.7.1 null-together invariant x 32 cellular-column subsets, hook
 *    flag = subset non-emptiness per the v1.81 attestation invariant). The
 *    remaining 2^9-64 masks violate documented group invariants and can never
 *    cross the wire; they are still exercised for field equality in the
 *    exhaustive round-trip test below.
 *  - [EnvironmentControlResultV1]: all 16 LEGAL carrier states (the 6 payload
 *    slots — the exact slots whose bare-writeParcelable write/read mismatch
 *    caused #186 — x legal errorCodeWire/diagnosticMessage combinations).
 *  - [AdvanceReceiptV1]: both states of advancedToItemId (exhausted = null).
 *  - every non-nullable DTO: one fully-populated vector.
 *
 * Every vector asserts BOTH directions: writeToParcel bytes == golden hex, and
 * golden hex -> CREATOR == instance (field equality). Additionally a separate
 * test round-trips EVERY 2^n combination (legal or not) so a field-equality
 * regression cannot hide in states the golden table does not enumerate.
 *
 * **Provenance & caveat.** Goldens were generated under Robolectric's JVM
 * Parcel simulation (Robolectric 4.14.1), which reproduces android.os.Parcel
 * encoding. The invariant this enforces is "both roots byte-identical" — if
 * the simulation itself changed, both roots' goldens change together and the
 * review of the golden diff is the guard.
 *
 * **How to regenerate (deliberate, reviewed act).** The wire layout is frozen
 * by §6.1 — a golden diff means EITHER a toolchain/codegen drift (must fix the
 * build, never the golden) OR a deliberate schema change (which per §6.1
 * requires a new carrier version, not in-place mutation — so a golden update
 * should be vanishingly rare and is always suspect).
 *
 * 1. `cd apps/cellrebel-auto && DUMP_PARCEL_GOLDENS=/tmp/golden-control.txt \
 *      ./gradlew --no-daemon :environment-control-v1:testDebugUnitTest \
 *      --tests '*ContractParcelGoldenWireTest*' --rerun-tasks`
 * 2. Paste /tmp/golden-control.txt into [GOLDEN] verbatim.
 * 3. Run the same module test from the OTHER root (apps/qianwangyou). If the
 *    two roots disagree, THAT is a #186 recurrence — fix the build, not the
 *    golden.
 * 4. Review the golden diff byte by byte; expect no diff at all.
 */
@RunWith(RobolectricTestRunner::class)
class ContractParcelGoldenWireTest {

    // ------------------------------------------------------------------ wiring

    private fun hex(bytes: ByteArray): String =
        bytes.joinToString("") { "%02x".format(it) }

    private fun unhex(s: String): ByteArray =
        ByteArray(s.length / 2) { i ->
            s.substring(i * 2, i * 2 + 2).toInt(16).toByte()
        }

    /** Bytes produced by writeToParcel — the payload an AIDL typed param puts on the wire. */
    private fun <T : Parcelable> encodeHex(value: T): String {
        val parcel = Parcel.obtain()
        try {
            value.writeToParcel(parcel, 0)
            parcel.setDataPosition(0)
            return hex(parcel.marshall())
        } finally {
            parcel.recycle()
        }
    }

    private inline fun <reified T : Parcelable> roundTrip(instance: T): T {
        val parcel = Parcel.obtain()
        try {
            parcel.writeParcelable(instance, 0)
            parcel.setDataPosition(0)
            @Suppress("DEPRECATION")
            return requireNotNull(parcel.readParcelable(T::class.java.classLoader))
        } finally {
            parcel.recycle()
        }
    }

    private fun goldenTable(): Map<String, String> =
        GOLDEN.lines()
            .map { it.trim() }
            .filter { it.isNotEmpty() && !it.startsWith("#") }
            .associate { line ->
                val sep = line.indexOf('|')
                require(sep > 0) { "bad golden line: $line" }
                line.substring(0, sep).trim() to line.substring(sep + 1).trim()
            }

    /** Decode golden hex through the generated CREATOR (the reader half of the contract). */
    private fun <T : Parcelable> decodeWith(hexString: String, creator: Parcelable.Creator<T>): T {
        val bytes = unhex(hexString)
        val parcel = Parcel.obtain()
        try {
            parcel.unmarshall(bytes, 0, bytes.size)
            parcel.setDataPosition(0)
            return creator.createFromParcel(parcel)
        } finally {
            parcel.recycle()
        }
    }

