    /** The 6 payload slots of the carrier, with the kind each one pairs with. */
    private fun payloadState(slot: Int): Triple<ContractResultKindV1, Parcelable, String> {
        val kind: ContractResultKindV1
        val payload: Parcelable
        when (slot) {
            0 -> { kind = ContractResultKindV1.DISCOVER; payload = fullCapabilitySnapshot() }
            1 -> { kind = ContractResultKindV1.PREFLIGHT; payload = fullPreflightReport() }
            2 -> { kind = ContractResultKindV1.APPLY; payload = applyReceipt() }
            3 -> {
                kind = ContractResultKindV1.OBSERVE
                payload = fullObservation()
            }
            4 -> { kind = ContractResultKindV1.RELEASE; payload = releaseReceipt() }
            5 -> { kind = ContractResultKindV1.COMPLETE_AND_ADVANCE; payload = advanceReceipt("item-golden-to-02") }
            else -> throw IllegalStateException()
        }
        return Triple(kind, payload, listOf("discover", "preflight", "apply", "observe", "release", "advance")[slot])
    }

    /** Slot indices: 0 discover, 1 preflight, 2 apply, 3 observe, 4 release, 5 advance, null = all payloads absent. */
    private fun carrier(
        kindWire: Int,
        errorCodeWire: Int?,
        diagnosticMessage: String?,
        slot: Int?,
    ): EnvironmentControlResultV1 = EnvironmentControlResultV1(
        resultSchemaVersion = EnvironmentControlResultV1.SCHEMA_VERSION,
        resultKindWire = kindWire,
        errorCodeWire = errorCodeWire,
        diagnosticMessage = diagnosticMessage,
        capabilitySnapshot = if (slot == 0) fullCapabilitySnapshot() else null,
        preflightReport = if (slot == 1) fullPreflightReport() else null,
        applyReceipt = if (slot == 2) applyReceipt() else null,
        environmentObservation = if (slot == 3) fullObservation() else null,
        releaseReceipt = if (slot == 4) releaseReceipt() else null,
        advanceReceipt = if (slot == 5) advanceReceipt("item-golden-to-02") else null,
    )

    // ------------------------------------------------------------------- tests

    /**
     * The #186 pin: every golden vector must reproduce byte-for-byte under
     * THIS root's kotlin-parcelize, in both directions.
     */
    @Test
    fun `golden vectors are byte-identical under this root's toolchain`() {
        val table = goldenTable()
        val vectors = canonicalVectors()
        assertEquals("golden vector count drifted — regenerate or fix the table", 171, table.size)
        assertEquals(
            "golden table and canonical vectors diverged — regenerate goldens or fix names",
            table.keys.sorted(),
            vectors.map { it.name }.toSet().sorted(),
        )
        for (v in vectors) {
            val expected = requireNotNull(table[v.name]) { "missing golden vector '${v.name}'" }
            val actual = encodeHex(v.instance)
            if (expected != actual) {
                fail(
                    "PARCEL LAYOUT DRIFT for '${v.name}' under this root's toolchain — this is " +
                        "the #186 failure mode. Fix the build, do not touch the golden.\n" +
                        "expected: $expected\n" +
                        "actual:   $actual",
                )
            }
            assertEquals(
                "decode of golden '${v.name}' drifted",
                v.instance,
                decodeWith(expected, v.creator),
            )
            assertEquals(
                "decode of actual bytes '${v.name}' mismatched",
                v.instance,
                decodeWith(actual, v.creator),
            )
        }
    }

    /**
     * Field-equality round trip for EVERY 2^n nullable combination, including
     * the group-invariant-violating masks the golden table deliberately skips:
     * parcelize is positional, so even states that cannot cross the wire must
     * not corrupt their neighbours.
     */
    @Test
    fun `every nullable combination round trips with field equality`() {
        for (mask in 0 until 16) {
            roundTrip(
                preflightReport(
                    waitUntilEpochMs = if (mask and 1 != 0) 5_555_555_555_001L else null,
                    scheduleItemId = if (mask and 2 != 0) "item-golden-preflight-01" else null,
                    scheduleVersion = if (mask and 4 != 0) 6_060L else null,
                    exhausted = if (mask and 8 != 0) true else null,
                ),
            ).let { restored ->
                assertEquals(if (mask and 1 != 0) 5_555_555_555_001L else null, restored.waitUntilEpochMs)
                assertEquals(if (mask and 2 != 0) "item-golden-preflight-01" else null, restored.scheduleItemId)
                assertEquals(if (mask and 4 != 0) 6_060L else null, restored.scheduleVersion)
                assertEquals(if (mask and 8 != 0) true else null, restored.exhausted)
            }
        }

        for (mask in 0 until 64) {
            val restored = roundTrip(
                observation(
                    continuitySinceEpochMs = if (mask and 1 != 0) 2_222_222_222_003L else null,
                    continuitySinceElapsedRealtimeMs = if (mask and 2 != 0) 2_222_222_222_004L else null,
                    deliveryModeWire = if (mask and 4 != 0) DeliveryModeV1.HOOK.wire else null,
                    effectiveLatitude = if (mask and 8 != 0) -33.8688197 else null,
                    effectiveLongitude = if (mask and 16 != 0) 151.2092955 else null,
                    isMock = if (mask and 32 != 0) true else null,
                ),
            )
            assertEquals(if (mask and 1 != 0) 2_222_222_222_003L else null, restored.continuitySinceEpochMs)
            assertEquals(if (mask and 2 != 0) 2_222_222_222_004L else null, restored.continuitySinceElapsedRealtimeMs)
            assertEquals(
                if (mask and 4 != 0) DeliveryModeV1.HOOK.wire else null,
                restored.deliveryModeWire,
            )
            assertEquals(if (mask and 8 != 0) -33.8688197 else null, restored.effectiveLatitude)
            assertEquals(if (mask and 16 != 0) 151.2092955 else null, restored.effectiveLongitude)
            assertEquals(if (mask and 32 != 0) true else null, restored.isMock)
        }

        // ALL 512 masks of the 9 nullable fields (legal and invariant-violating).
        for (scheduleMask in 0 until 16) {
            for (cellMask in 0 until 32) {
                val anyColumn = cellMask != 0
                val restored = roundTrip(
                    CapabilitySnapshotV1(
                        serviceVersion = "3.7.7-golden",
                        supportedModeWires = listOf(DeliveryModeV1.SYSTEM_MOCK.wire),
                        supportedVerificationLevelWires = listOf(VerificationLevelV1.NONE.wire),
                        continuityCoverageWire = ContinuityCoverageV1.FULL.wire,
                        environmentRevision = 999L,
                        profileRefs = listOf("p-golden-1"),
                        scheduleRefs = listOf("s-golden-1"),
                        currentScheduleId = if (scheduleMask and 1 != 0) "sched-golden-01" else null,
                        currentItemId = if (scheduleMask and 2 != 0) "item-golden-02" else null,
                        scheduleVersion = if (scheduleMask and 4 != 0) 7_070L else null,
                        exhausted = if (scheduleMask and 8 != 0) false else null,
                        configuredCellCi = if (cellMask and 1 != 0) 289_001L else null,
                        configuredCellTac = if (cellMask and 2 != 0) 31461 else null,
                        configuredCellPci = if (cellMask and 4 != 0) 210 else null,
                        configuredCellMcc = if (cellMask and 8 != 0) "460" else null,
                        configuredCellMnc = if (cellMask and 16 != 0) "00" else null,
                        cellularHookConfigured = anyColumn,
                    ),
                )
                assertEquals(if (scheduleMask and 1 != 0) "sched-golden-01" else null, restored.currentScheduleId)
                assertEquals(if (scheduleMask and 2 != 0) "item-golden-02" else null, restored.currentItemId)
                assertEquals(if (scheduleMask and 4 != 0) 7_070L else null, restored.scheduleVersion)
                assertEquals(if (scheduleMask and 8 != 0) false else null, restored.exhausted)
                assertEquals(if (cellMask and 1 != 0) 289_001L else null, restored.configuredCellCi)
                assertEquals(if (cellMask and 2 != 0) 31461 else null, restored.configuredCellTac)
                assertEquals(if (cellMask and 4 != 0) 210 else null, restored.configuredCellPci)
                assertEquals(if (cellMask and 8 != 0) "460" else null, restored.configuredCellMcc)
                assertEquals(if (cellMask and 16 != 0) "00" else null, restored.configuredCellMnc)
            }
        }

        // ALL 256 carrier masks over (errorCodeWire, diagnosticMessage, 6 payload slots).
        for (combo in 0 until 256) {
            val slot = (combo shr 2) and 7 // 0..5 meaningful, 6/7 => all payloads null
            val restored = roundTrip(
                EnvironmentControlResultV1(
                    resultSchemaVersion = EnvironmentControlResultV1.SCHEMA_VERSION,
                    resultKindWire = ContractResultKindV1.ERROR.wire,
                    errorCodeWire = if (combo and 1 != 0) ContractErrorCodeV1.INTERNAL_FAILURE.wire else null,
                    diagnosticMessage = if (combo and 2 != 0) "diagnostic-golden-01" else null,
                    capabilitySnapshot = if (slot == 0) fullCapabilitySnapshot() else null,
                    preflightReport = if (slot == 1) fullPreflightReport() else null,
                    applyReceipt = if (slot == 2) applyReceipt() else null,
                    environmentObservation = if (slot == 3) fullObservation() else null,
                    releaseReceipt = if (slot == 4) releaseReceipt() else null,
                    advanceReceipt = if (slot == 5) advanceReceipt("item-golden-to-02") else null,
                ),
            )
            assertEquals(
                if (combo and 1 != 0) ContractErrorCodeV1.INTERNAL_FAILURE.wire else null,
                restored.errorCodeWire,
            )
            assertEquals(
                if (combo and 2 != 0) "diagnostic-golden-01" else null,
                restored.diagnosticMessage,
            )
            assertEquals(slot == 0, restored.capabilitySnapshot != null)
            assertEquals(slot == 1, restored.preflightReport != null)
            assertEquals(slot == 2, restored.applyReceipt != null)
            assertEquals(slot == 3, restored.environmentObservation != null)
            assertEquals(slot == 4, restored.releaseReceipt != null)
            assertEquals(slot == 5, restored.advanceReceipt != null)
        }
    }

    /**
     * Regeneration gate: a no-op in normal runs. Point DUMP_PARCEL_GOLDENS at a
     * file path to emit the canonical GOLDEN literal (see class KDoc step 1).
     */
    @Test
    fun `dump golden vectors for regeneration is gated`() {
        val dumpPath = System.getenv("DUMP_PARCEL_GOLDENS") ?: return
        java.io.File(dumpPath).writeText(goldenLiteral())
        println("ContractParcelGoldenWireTest golden literal written to $dumpPath")
    }

    // ------------------------------------------------------- golden generation

    /**
     * One golden vector: the frozen name, the instance, and the generated
     * CREATOR that decodes its bytes — the same static CREATOR an AIDL stub
     * uses on the read side (there is deliberately no class-name prefix in
     * writeToParcel output, so [Parcel.readParcelable] must NOT be used here).
     */
    private class GoldenVector<T : Parcelable>(
        val name: String,
        val instance: T,
        val creator: Parcelable.Creator<T>,
    )

    private fun <T : Parcelable> vec(
        name: String,
        instance: T,
        creator: Parcelable.Creator<T>,
    ): GoldenVector<T> = GoldenVector(name, instance, creator)

    /** Canonical instance list — the single source the dump (and the golden test) walk. */
    private fun canonicalVectors(): List<GoldenVector<*>> {
        val vectors = mutableListOf<GoldenVector<*>>()
        vectors.add(vec("intent/single", intent(), ContractCreators.environmentIntent()))
        vectors.add(vec("preflight-request/single", preflightRequest(), ContractCreators.preflightRequest()))
        vectors.add(vec("apply-request/single", applyRequest(), ContractCreators.applyRequest()))
        vectors.add(vec("apply-receipt/single", applyReceipt(), ContractCreators.applyReceipt()))
        vectors.add(vec("observe-request/single", observeRequest(), ContractCreators.observeRequest()))
        vectors.add(vec("release-request/single", releaseRequest(), ContractCreators.releaseRequest()))
        vectors.add(vec("release-receipt/single", releaseReceipt(), ContractCreators.releaseReceipt()))
        vectors.add(
            vec(
                "complete-advance-request/single", completeAndAdvanceRequest(),
                ContractCreators.completeAndAdvanceRequest(),
            ),
        )
        vectors.add(vec("completion-proof/single", completionProof(), ContractCreators.completionProof()))
        vectors.add(vec("advance-receipt/0", advanceReceipt("item-golden-to-02"), ContractCreators.advanceReceipt()))
        vectors.add(vec("advance-receipt/1", advanceReceipt(null), ContractCreators.advanceReceipt()))
        for (mask in 0 until 16) {
            vectors.add(
                vec(
                    "preflight-report/" + mask.toBinaryString(4),
                    preflightReport(
                        waitUntilEpochMs = if (mask and 1 != 0) 5_555_555_555_001L else null,
                        scheduleItemId = if (mask and 2 != 0) "item-golden-preflight-01" else null,
                        scheduleVersion = if (mask and 4 != 0) 6_060L else null,
                        exhausted = if (mask and 8 != 0) true else null,
                    ),
                    ContractCreators.preflightReport(),
                ),
            )
        }
        for (mask in 0 until 64) {
            vectors.add(
                vec(
                    "observation/" + mask.toBinaryString(6),
                    observation(
                        continuitySinceEpochMs = if (mask and 1 != 0) 2_222_222_222_003L else null,
                        continuitySinceElapsedRealtimeMs = if (mask and 2 != 0) 2_222_222_222_004L else null,
                        deliveryModeWire = if (mask and 4 != 0) DeliveryModeV1.HOOK.wire else null,
                        effectiveLatitude = if (mask and 8 != 0) -33.8688197 else null,
                        effectiveLongitude = if (mask and 16 != 0) 151.2092955 else null,
                        isMock = if (mask and 32 != 0) true else null,
                    ),
                    ContractCreators.environmentObservation(),
                ),
            )
        }
        for (schedulePopulated in listOf(false, true)) {
            for (cellMask in 0 until 32) {
                vectors.add(
                    vec(
                        "capability/s${if (schedulePopulated) 1 else 0}-c" + cellMask.toBinaryString(5),
                        capabilitySnapshot(schedulePopulated, cellMask),
                        ContractCreators.capabilitySnapshot(),
                    ),
                )
            }
        }
        for (combo in 0 until 4) {
            vectors.add(
                vec(
                    "carrier/error/e" + (combo and 1) + "d" + (combo shr 1),
                    carrier(
                        kindWire = ContractResultKindV1.ERROR.wire,
                        errorCodeWire = if (combo and 1 != 0) ContractErrorCodeV1.INTERNAL_FAILURE.wire else null,
                        diagnosticMessage = if (combo and 2 != 0) "diagnostic-golden-01" else null,
                        slot = null,
                    ),
                    ContractCreators.environmentControlResult(),
                ),
            )
        }
        for (slot in 0 until 6) {
            for (diagnostic in listOf(false, true)) {
                vectors.add(
                    vec(
                        "carrier/" + payloadState(slot).third + "/e0d" + (if (diagnostic) 1 else 0),
                        carrier(
                            kindWire = payloadState(slot).first.wire,
                            errorCodeWire = null,
                            diagnosticMessage = if (diagnostic) "diagnostic-golden-02" else null,
                            slot = slot,
                        ),
                        ContractCreators.environmentControlResult(),
                    ),
                )
            }
        }
        return vectors
    }

    private fun goldenLiteral(): String = buildString {
        append("# ContractParcelGoldenWireTest golden vectors (#186 byte-layout pin).\n")
        append("# Format: name|lowercase-hex-of-writeToParcel-output. Regenerate via DUMP_PARCEL_GOLDENS (see class KDoc).\n")
        for (v in canonicalVectors()) {
            append(v.name).append('|').append(encodeHex(v.instance)).append('\n')
        }
    }

    private fun Int.toBinaryString(bits: Int): String {
        var out = ""
        for (i in bits - 1 downTo 0) out += if ((this shr i) and 1 != 0) "1" else "0"
        return out
    }

